source(file.path("r","feature_settimanali.R")); d<-as.Date("2026-08-25"); cols<-paste0("x",1:41); l<-list(minuti=cols[1:40],punti=cols[2:41]); dir<-tempfile(); p<-pubblica_feature_settimanali(l,d,cols,dir); stopifnot(file.exists(p),identical(leggi_feature_settimanali(d,cols,dir),l)); dir2<-tempfile(); aggiorna_feature_settimanali(l["minuti"],d,cols,dir2); aggiorna_feature_settimanali(l["punti"],d,cols,dir2); stopifnot(identical(leggi_feature_settimanali(d,cols,dir2),l)); cat("test_feature_settimanali: OK\n")
